// @ts-check
// The PR quality report (V13-QA-017; REQ-CICD-002; docs/qa/M1_OPEN_QA_ROWS_DESIGN.md §10, ruling D4). One Markdown
// report per CI job, built only from what the job's test runs already wrote: Playwright's JSON report and Vitest's
// JUnit XML. Nothing is generated by a model, nothing is posted as a PR comment and no token is used: CI appends the
// report to the job's step summary ($GITHUB_STEP_SUMMARY) and keeps a copy in the job's artifact.
//
// Sections (§10.1): failed tests (and flaky ones), screenshot comparisons, UX findings (the reflow checks of
// tests/a11y/reflow.a11y.spec.ts), accessibility findings (axe), performance changes (not measured in M1: no baseline
// or budget exists) and recommended corrections (a fixed table, never invented per run).
//
// SEC's binding rules for this report (#132): inputs come through the environment, never `${{ }}` inside `run:`;
// connection strings and anything shaped `scheme://user:password@` are redacted before anything is written.
//
// Usage (CI): PR_REPORT_TITLE, PR_REPORT_PLAYWRIGHT and PR_REPORT_JUNIT (comma-separated paths; a missing file is
// reported as "not produced", never an error), PR_REPORT_OUT (the copy for the artifact) and GITHUB_STEP_SUMMARY.
// SYNTHETIC test data only; reads local files, writes the report.
import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, join, relative } from "node:path";
import { pathToFileURL } from "node:url";

/** The attachment names the specs use for structured findings (tests/a11y). */
export const A11Y_ATTACHMENT = "a11y-violations";
export const REFLOW_ATTACHMENT = "reflow-findings";

/** At most this many rows per section; the rest are counted, so the summary stays well under GitHub's 1 MiB. */
export const MAX_ROWS = 50;

/**
 * Recommended corrections (§10.1): the usual correction for each axe rule and reflow check, written once here and
 * linked to the UX backlog's conventions. A finding without a row gets the fallback, never an invented one.
 * @type {Readonly<Record<string, string>>}
 */
export const CORRECTIONS = {
  "axe:color-contrast":
    "Use a token pair from the design tokens that meets 4.5:1 (3:1 for large text); never a hard-coded colour.",
  "axe:link-in-text-block":
    "Underline links inside text, or give them 3:1 contrast with the text and a non-colour cue.",
  "axe:label": "Give the control a visible <label> (or aria-labelledby) with text from lib/i18n.",
  "axe:button-name":
    "Give the button an accessible name from lib/i18n (visible text, or aria-label for an icon).",
  "axe:link-name": "Give the link discernible text from lib/i18n.",
  "axe:image-alt": 'Give the image an alt text from lib/i18n, or alt="" when it is decorative.',
  "axe:landmark-one-main": "Render exactly one <main> per page (the platform shell's).",
  "axe:region": "Put the content inside a landmark (main, nav, header, footer or a named region).",
  "axe:document-title": "Give the page a title through its metadata (lib/i18n).",
  "axe:html-has-lang": "Set lang (and dir) on <html> from the active locale.",
  "axe:aria-allowed-attr": "Remove ARIA attributes the element's role does not allow.",
  "axe:scrollable-region-focusable":
    'Make the scroll container a named region: role="region", an accessible name and tabindex="0".',
  "reflow:1":
    "Let the flex or grid child shrink (min-inline-size: 0) or wrap; scroll wide tables inside a named region.",
  "reflow:2": "Let the navigation or tab list wrap or scroll as a named region at 320 px.",
  "reflow:3": "Let the text wrap (no fixed block-size with overflow hidden); use logical properties.",
  "reflow:4": 'Give the inline scroll container role="region", an accessible name and tabindex="0".',
  "reflow:5": "Keep the skip link inside the viewport when focused (logical inset, no fixed inline offset).",
  "reflow:6": "Keep the open menu inside the viewport at 320 px: logical inset and max-inline-size: 100%.",
};
export const CORRECTION_FALLBACK =
  "No listed correction: record it in docs/design/reviews/UX_BACKLOG.md with its evidence and route it to the owner.";

/** Redacts connection strings and credentials in URLs (SEC #132, rule 4). @param {unknown} text */
export function redact(text) {
  return String(text)
    .replace(/\b(postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis):\/\/[^\s"'`<>]+/gi, "$1://[redacted]")
    .replace(/\b([a-z][a-z0-9+.-]*:\/\/)[^\s/:@"'`<>]+:[^\s@"'`<>]+@/gi, "$1[redacted]@");
}

// eslint-disable-next-line no-control-regex
const ANSI = /\u001b\[[0-9;]*[A-Za-z]/g;

/** The first non-empty line of an error, without colour codes, redacted and cut to 300 characters. @param {unknown} text */
export function firstLine(text) {
  const line = String(text ?? "")
    .replace(ANSI, "")
    .split("\n")
    .map((l) => l.trim())
    .find((l) => l !== "");
  const out = redact(line ?? "");
  return out.length > 300 ? `${out.slice(0, 299)}…` : out;
}

/** Text for a Markdown table cell: one line, pipes and backticks escaped, HTML angle brackets neutralised. @param {unknown} text */
export function cell(text) {
  return redact(String(text ?? ""))
    .replace(/\r?\n/g, " ")
    .replace(/\|/g, "\\|")
    .replace(/`/g, "'")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/**
 * @typedef {{ kind: "failed" | "flaky", title: string, where: string, error: string }} TestRow
 * @typedef {{ title: string, name: string, expected?: string, actual?: string, diff?: string }} ShotRow
 * @typedef {{ page: string, language?: string, condition?: string, check: number | string, detail: string }} ReflowRow
 * @typedef {{ rule: string, impact: string, page: string, nodes: number }} AxeRow
 * @typedef {{ tests: TestRow[], shots: ShotRow[], reflow: ReflowRow[], axe: AxeRow[], reflowFailures: TestRow[] }} Findings
 */

/** @returns {Findings} */
export const emptyFindings = () => ({ tests: [], shots: [], reflow: [], axe: [], reflowFailures: [] });

/** @param {string} p @param {string} root */
const rel = (p, root) => (isAbsolute(p) ? relative(root, p) : p).split("\\").join("/");

/** @param {any} attachment */
function attachmentJson(attachment) {
  try {
    const raw =
      attachment.body !== undefined
        ? Buffer.from(attachment.body, "base64").toString("utf8")
        : attachment.path && existsSync(attachment.path)
          ? readFileSync(attachment.path, "utf8")
          : "";
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/**
 * Reads a Playwright JSON report (the `json` reporter) into findings.
 * @param {any} report @param {string} root the repository root, for relative paths @param {Findings} into
 */
export function readPlaywright(report, root, into = emptyFindings()) {
  // spec files are relative to the configuration's rootDir (its testDir)
  const base = typeof report?.config?.rootDir === "string" ? report.config.rootDir : "";
  /** @param {string} file */
  const fileOf = (file) => rel(base && !isAbsolute(file) ? join(base, file) : file, root);
  /** @param {any} suite @param {string[]} titles */
  const walk = (suite, titles) => {
    const here = suite.title && !suite.file?.endsWith(suite.title) ? [...titles, suite.title] : titles;
    for (const spec of suite.specs ?? []) {
      for (const t of spec.tests ?? []) {
        const results = t.results ?? [];
        const last = results[results.length - 1];
        const title = [...here, spec.title].join(" › ") + (t.projectName ? ` [${t.projectName}]` : "");
        const where = `${fileOf(spec.file ?? suite.file ?? "")}:${spec.line ?? 0}`;
        if (t.status === "unexpected" || t.status === "flaky") {
          const failing =
            t.status === "flaky" ? results.find((/** @type {any} */ r) => r.status !== "passed") : last;
          const err = failing?.errors?.[0]?.message ?? failing?.error?.message ?? "";
          const row = {
            kind: /** @type {"failed"|"flaky"} */ (t.status === "flaky" ? "flaky" : "failed"),
            title,
            where,
            error: firstLine(err),
          };
          into.tests.push(row);
        }
        const reflowBefore = into.reflow.length;
        for (const r of results) {
          /** @type {Map<string, ShotRow>} */
          const shots = new Map();
          for (const a of r.attachments ?? []) {
            const m = /^(.*)-(expected|actual|diff)\.png$/.exec(a.name ?? "");
            if (m && a.path) {
              const key = m[1] ?? "";
              /** @type {ShotRow} */
              const row = shots.get(key) ?? { title, name: key };
              const which = /** @type {"expected"|"actual"|"diff"} */ (m[2]);
              row[which] = rel(a.path, root);
              shots.set(key, row);
            } else if (a.name === A11Y_ATTACHMENT) {
              for (const v of attachmentJson(a))
                into.axe.push({
                  rule: String(v.rule ?? ""),
                  impact: String(v.impact ?? ""),
                  page: String(v.page ?? ""),
                  nodes: Number(v.nodes ?? 0),
                });
            } else if (a.name === REFLOW_ATTACHMENT) {
              for (const f of attachmentJson(a))
                into.reflow.push({
                  page: String(f.page ?? ""),
                  language: f.language === undefined ? undefined : String(f.language),
                  condition: f.condition === undefined ? undefined : String(f.condition),
                  check: f.check ?? "",
                  detail: String(f.detail ?? ""),
                });
            }
          }
          for (const s of shots.values()) if (s.actual || s.diff) into.shots.push(s);
        }
        // a failed reflow test that attached no finding (checks 5 and 6, or an error before the measurement)
        if (
          t.status === "unexpected" &&
          into.reflow.length === reflowBefore &&
          /(^|\/)reflow\.a11y\.spec\.ts:/.test(where)
        )
          into.reflowFailures.push({
            kind: "failed",
            title,
            where,
            error: firstLine(last?.errors?.[0]?.message ?? ""),
          });
      }
    }
    for (const child of suite.suites ?? []) walk(child, here);
  };
  for (const s of report?.suites ?? []) walk(s, []);
  return into;
}

/** @param {string} s */
const xmlText = (s) =>
  s
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, "&");

/** @param {string} tag @param {string} name */
const attr = (tag, name) => {
  const m = new RegExp(`\\s${name}="([^"]*)"`).exec(tag);
  return m ? xmlText(m[1] ?? "") : undefined;
};

/**
 * Reads a JUnit XML report (Vitest's `junit` reporter) into findings: each test case with a failure or error.
 * @param {string} xml @param {Findings} into
 */
export function readJUnit(xml, into = emptyFindings()) {
  for (const m of xml.matchAll(/<testcase\b([^>]*?)(?:\/>|>([\s\S]*?)<\/testcase>)/g)) {
    const body = m[2] ?? "";
    const fail = /<(failure|error)\b([^>]*?)(?:\/>|>([\s\S]*?)<\/\1>)/.exec(body);
    if (!fail) continue;
    const tag = m[1] ?? "";
    const file = attr(tag, "file") ?? attr(tag, "classname") ?? "";
    const message = attr(fail[2] ?? "", "message") ?? xmlText(fail[3] ?? "");
    into.tests.push({
      kind: "failed",
      title: attr(tag, "name") ?? "",
      where: file,
      error: firstLine(message),
    });
  }
  return into;
}

/** @param {string[]} header @param {string[][]} rows */
function table(header, rows) {
  const shown = rows.slice(0, MAX_ROWS);
  const lines = [`| ${header.join(" | ")} |`, `| ${header.map(() => "---").join(" | ")} |`];
  for (const r of shown) lines.push(`| ${r.map(cell).join(" | ")} |`);
  if (rows.length > shown.length)
    lines.push("", `… and ${rows.length - shown.length} more (see the job's artifact).`);
  return lines.join("\n");
}

/**
 * Builds the report. `inputs` names each input and whether it was produced, so a missing report never reads as
 * "nothing failed".
 * @param {string} title @param {Findings} f @param {{ name: string, produced: boolean }[]} inputs
 */
export function buildReport(title, f, inputs) {
  const out = [`## PR quality report: ${cell(title)}`, ""];
  const missing = inputs.filter((i) => !i.produced);
  out.push(
    `Built from this job's own test reports (${inputs.map((i) => `\`${cell(i.name)}\``).join(", ") || "none named"}); nothing in it is generated.`,
  );
  if (missing.length === inputs.length)
    out.push(
      "",
      "**No test report was produced.** The job stopped before its tests wrote one, so the empty sections below prove nothing.",
    );
  else if (missing.length)
    out.push(
      "",
      `Named but not produced in this run: ${missing.map((i) => `\`${cell(i.name)}\``).join(", ")}.`,
    );

  const failed = f.tests.filter((t) => t.kind === "failed");
  const flaky = f.tests.filter((t) => t.kind === "flaky");
  out.push("", `### Failed tests (${failed.length})`, "");
  out.push(
    failed.length
      ? table(
          ["Test", "File:line", "First error line"],
          failed.map((t) => [t.title, t.where, t.error]),
        )
      : "None.",
  );
  if (flaky.length)
    out.push(
      "",
      `### Flaky tests: passed on a retry (${flaky.length})`,
      "",
      table(
        ["Test", "File:line", "First failure"],
        flaky.map((t) => [t.title, t.where, t.error]),
      ),
    );

  out.push("", `### Screenshots (${f.shots.length})`, "");
  out.push(
    f.shots.length
      ? table(
          ["Test", "Snapshot", "Expected", "Actual", "Diff"],
          f.shots.map((s) => [
            s.title,
            s.name,
            s.expected ?? "(none: missing baseline)",
            s.actual ?? "",
            s.diff ?? "",
          ]),
        )
      : "No screenshot comparison failed.",
  );

  const uxRows = [
    ...f.reflow.map((r) => [r.page, r.language ?? "", r.condition ?? "", `check ${r.check}`, r.detail]),
    ...f.reflowFailures.map((t) => ["", "", t.title, "test failed", t.error]),
  ];
  out.push("", `### UX findings: text resize and reflow (${uxRows.length})`, "");
  out.push(uxRows.length ? table(["Page", "Language", "Condition", "Check", "Detail"], uxRows) : "None.");

  out.push("", `### Accessibility findings: axe (${f.axe.length})`, "");
  out.push(
    f.axe.length
      ? table(
          ["Rule", "Impact", "Page", "Nodes"],
          f.axe.map((a) => [a.rule, a.impact, a.page, String(a.nodes)]),
        )
      : "None reported. This is not a claim of conformance: axe checks a subset of WCAG, and the manual checklist (REQ-A11Y-003) covers the rest.",
  );

  out.push(
    "",
    "### Performance changes",
    "",
    "Not measured in M1: no performance baseline or budget exists. This row of REQ-CICD-002 stays open until one has a source and an ARCH decision.",
  );

  const keys = [
    ...new Set([...f.axe.map((a) => `axe:${a.rule}`), ...f.reflow.map((r) => `reflow:${r.check}`)]),
  ].sort();
  out.push("", "### Recommended corrections", "");
  out.push(
    keys.length
      ? table(
          ["Finding", "Usual correction"],
          keys.map((k) => [k, CORRECTIONS[k] ?? CORRECTION_FALLBACK]),
        ) +
          "\n\nFrom the fixed table in `tests/report/pr-report.mjs`; items are tracked in `docs/design/reviews/UX_BACKLOG.md`."
      : "None needed.",
  );
  return redact(out.join("\n")) + "\n";
}

/** @param {string | undefined} list */
const paths = (list) =>
  (list ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter((s) => s !== "");

/**
 * Reads the inputs named in the environment and returns the report.
 * @param {Readonly<Record<string, string | undefined>>} env @param {string} root
 */
export function reportFromEnv(env, root = process.cwd()) {
  const f = emptyFindings();
  /** @type {{ name: string, produced: boolean }[]} */
  const inputs = [];
  for (const p of paths(env.PR_REPORT_PLAYWRIGHT)) {
    const produced = existsSync(p);
    inputs.push({ name: p, produced });
    if (produced) readPlaywright(JSON.parse(readFileSync(p, "utf8")), root, f);
  }
  for (const p of paths(env.PR_REPORT_JUNIT)) {
    const produced = existsSync(p);
    inputs.push({ name: p, produced });
    if (produced) readJUnit(readFileSync(p, "utf8"), f);
  }
  return buildReport(env.PR_REPORT_TITLE?.trim() || "tests", f, inputs);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const report = reportFromEnv(process.env);
  const out = process.env.PR_REPORT_OUT?.trim();
  if (out) {
    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, report);
  }
  const summary = process.env.GITHUB_STEP_SUMMARY?.trim();
  if (summary) appendFileSync(summary, report);
  else process.stdout.write(report);
}
